const berlinDay = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Europe/Berlin',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
});

const today = berlinDay.format(new Date());

function clean(value) {
  return typeof value === 'string'
    ? value.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim()
    : '';
}

function dayKey(value) {
  if (!value) return null;
  const date = new Date(value);
  return Number.isNaN(date.valueOf()) ? null : berlinDay.format(date);
}

const seen = new Set();
const articles = $input.all()
  .map(({ json }) => {
    const title = clean(json.title);
    const link = clean(json.link || json.guid);
    const publishedAt = json.isoDate || json.pubDate || json.date || null;
    const source = clean(json.creator || json.author || json['dc:creator'] || 'Google News');
    const snippet = clean(json.contentSnippet || json.content || json.description);

    return { title, link, publishedAt, source, snippet };
  })
  .filter((article) => article.title && article.link)
  .filter((article) => {
    const key = `${article.title}|${article.link}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  })
  .sort((a, b) => new Date(b.publishedAt || 0) - new Date(a.publishedAt || 0));

const todaysArticles = articles.filter((article) => dayKey(article.publishedAt) === today);
const selectedArticles = (todaysArticles.length > 0 ? todaysArticles : articles).slice(0, 25);

const articleDigest = selectedArticles.map((article, index) => [
  `${index + 1}. ${article.title}`,
  `Quelle: ${article.source}`,
  `Zeit: ${article.publishedAt || 'unbekannt'}`,
  `Link: ${article.link}`,
  `Kurztext: ${article.snippet || 'kein Kurztext verfuegbar'}`,
].join('\n')).join('\n\n');

const systemPrompt = [
  'Du bist ein praeziser deutschsprachiger Nachrichtenredakteur.',
  'Fasse nur die gelieferten Google-News-RSS-Artikel zusammen.',
  'Erfinde keine Fakten und markiere Unsicherheit klar.',
  'Gib eine kompakte, gut lesbare Ausgabe auf Deutsch zurueck.',
].join(' ');

const userPrompt = selectedArticles.length === 0
  ? `Heute ist ${today} in der Zeitzone Europe/Berlin. Im Google-News-RSS-Feed wurden keine Artikel gefunden. Gib eine kurze Meldung aus, dass keine Nachrichten zusammengefasst werden konnten.`
  : [
      `Heute ist ${today} in der Zeitzone Europe/Berlin.`,
      todaysArticles.length > 0
        ? `Fasse die folgenden ${selectedArticles.length} heutigen Google-News-Artikel zusammen.`
        : `Im Feed waren keine eindeutig heutigen Artikel. Fasse die neuesten ${selectedArticles.length} Google-News-Artikel zusammen und weise darauf hin.`,
      '',
      'Bitte liefere:',
      '1. Eine Executive Summary mit 5 bis 7 Bulletpoints.',
      '2. Die wichtigsten Themencluster mit je 2 bis 3 Saetzen.',
      '3. Eine kurze Liste der Top-Links mit Titel und URL.',
      '',
      articleDigest,
    ].join('\n');

return [{
  json: {
    date: today,
    source: 'Google News Deutschland RSS',
    feedUrl: 'https://news.google.com/rss?hl=de&gl=DE&ceid=DE:de',
    articleCount: selectedArticles.length,
    onlyLatestArticles: todaysArticles.length === 0,
    articles: selectedArticles,
    llmRequest: {
      model: 'qwen3.8',
      temperature: 0.2,
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userPrompt },
      ],
    },
  },
}];

const content = $json.choices?.[0]?.message?.content
  || $json.output_text
  || $json.text
  || JSON.stringify($json, null, 2);

return [{
  json: {
    generatedAt: new Date().toISOString(),
    model: $json.model || 'qwen3.8',
    summary: content,
    usage: $json.usage || null,
  },
}];

